<?php
get_header();
while ( have_posts() ) : the_post();
    if ( post_password_required() ) { echo '<article class="reading-width">'; the_title( '<h1>', '</h1>' ); the_content(); echo '</article>'; continue; }
    $id = get_the_ID(); $item = \MSC\Reviews::item( $id ); $score = \MSC\Reviews::score( get_post_meta( $id, '_msc_review_score', true ) );
    $row = null === $score ? null : array( 'provider' => 'editorial', 'name' => msc_screen_identity()['name'], 'score' => $score, 'max' => 10, 'award' => \MSC\Reviews::award( $score ) );
    $verdict = get_post_meta( $id, '_msc_review_verdict', true ); $platform = get_post_meta( $id, '_msc_review_platform', true );
?>
<article class="review-article">
<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="<?php echo esc_url( home_url( '/' ) ); ?>">Home</a><span>/</span><a href="<?php echo esc_url( get_post_type_archive_link( 'msc_review' ) ); ?>">Reviews</a><?php if ( $item ) { ?><span>/</span><a href="<?php echo esc_url( \MSC\Presentation::url( $item ) ); ?>"><?php echo esc_html( $item['data']['title'] ); ?></a><?php } ?></nav>
<header class="review-header"><p class="eyebrow"><?php echo esc_html( msc_screen_identity()['name'] ); ?> Review<?php echo $platform ? ' · ' . esc_html( $platform ) : ''; ?></p><h1><?php the_title(); ?></h1><p class="review-byline">By <?php the_author(); ?> · <time datetime="<?php echo esc_attr( get_the_date( 'c' ) ); ?>"><?php echo esc_html( get_the_date() ); ?></time></p></header>
<div class="review-featured-image"><?php if ( has_post_thumbnail() ) { the_post_thumbnail( 'large', array( 'class' => 'review-cover' ) ); } elseif ( $item ) { echo \MSC\Presentation::image( $item, 'review-cover', 'large' ); echo \MSC\Attribution::collect_image( $item ); } if ( $row ) { echo \MSC\ReviewScores::badge_row( $row ); } ?></div>
<div class="review-reading-layout"><div class="review-article-body story-copy"><div class="prose"><?php the_content(); ?></div></div><aside class="review-summary<?php echo $row && $row['award'] ? ' award-' . esc_attr( $row['award'] ) : ''; ?>"><p class="eyebrow">Review score</p><?php if ( null !== $score ) { ?><p class="review-score-value"><?php echo esc_html( \MSC\Reviews::number( $score ) ); ?><small>/10</small></p><?php if ( $row['award'] ) { ?><p class="review-award-label"><?php echo esc_html( ucfirst( $row['award'] ) . ' recommendation' ); ?></p><?php } } if ( $item ) { ?><a class="text-link" href="<?php echo esc_url( \MSC\Presentation::url( $item ) ); ?>">View <?php echo esc_html( $item['data']['title'] ); ?></a><?php } ?></aside></div>
<section class="review-verdict<?php echo $row && $row['award'] ? ' award-' . esc_attr( $row['award'] ) : ''; ?>"><div class="review-verdict-heading"><div><p class="eyebrow"><?php echo esc_html( msc_screen_identity()['name'] ); ?></p><h2>Final Verdict</h2></div><?php if ( null !== $score ) { ?><p class="review-score-value"><?php echo esc_html( \MSC\Reviews::number( $score ) ); ?><small>/10</small></p><?php } ?></div><?php if ( $verdict ) { ?><div class="prose"><?php echo wpautop( esc_html( $verdict ) ); ?></div><?php } ?><div class="review-pros-cons"><?php foreach ( array( 'pros' => 'Positives', 'cons' => 'Negatives' ) as $key => $label ) { $lines = array_filter( array_map( 'trim', preg_split( '/\R/u', get_post_meta( $id, '_msc_review_' . $key, true ) ) ) ); if ( ! $lines ) { continue; } ?><div class="review-<?php echo esc_attr( $key ); ?>"><h3><?php echo esc_html( $label ); ?></h3><ul><?php foreach ( $lines as $line ) { echo '<li>' . esc_html( $line ) . '</li>'; } ?></ul></div><?php } ?></div></section>
</article>
<?php endwhile; get_footer(); ?>
